using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace Captura {
 public class EncoderChoice { public int Index;public string Name;public override string ToString(){return Index<0?"CPU · software":"GPU · "+Name;} }
 public static class VideoProfiles {
  public static readonly int[] Rates={30,60,120,240};
  public static int NormalizeFps(int n){foreach(int f in Rates)if(n==f)return n;return n>=120?120:n>=60?60:30;}
  public static List<EncoderChoice> Encoders(){var list=new List<EncoderChoice>{new EncoderChoice{Index=-1,Name="CPU"}};try{using(var p=new Process{StartInfo=new ProcessStartInfo("nvidia-smi.exe","--query-gpu=index,name --format=csv,noheader"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){p.Start();var read=p.StandardOutput.ReadToEndAsync();var err=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(4000)){p.Kill();return list;}foreach(string row in read.Result.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){int comma=row.IndexOf(',');int index;if(comma>0&&int.TryParse(row.Substring(0,comma).Trim(),out index))list.Add(new EncoderChoice{Index=index,Name=row.Substring(comma+1).Trim()});}}}catch{}return list;}
  public static Size OutputSize(string resolution,Size source){int height=resolution=="720p"?720:resolution=="1080p"?1080:resolution=="1440p"?1440:resolution=="2160p"?2160:source.Height;if(height==source.Height)return source;return new Size(Math.Max(2,(int)Math.Round((double)source.Width*height/source.Height/2)*2),height);}
  public static void Copy(Preferences a,Preferences b){b.VideoFps=a.VideoFps;b.VideoNvenc=a.VideoNvenc;b.VideoGpu=a.VideoGpu;b.VideoCodec=a.VideoCodec;b.VideoContainer=a.VideoContainer;b.VideoResolution=a.VideoResolution;b.VideoQuality=a.VideoQuality;b.VideoMinMbps=a.VideoMinMbps;b.VideoMaxMbps=a.VideoMaxMbps;b.SeparateMp3=a.SeparateMp3;}
  public static string Codec(RecordingRequest r){return (r.Codec=="H.265"?"hevc":"h264")+(r.UseNvenc?"_nvenc":"");}
  public static string EncoderArguments(RecordingRequest r){string codec=r.Codec=="H.265"?"hevc":"h264";string quality=r.Quality=="Alta"?"18":r.Quality=="Leve"?"28":"23";string result=r.UseNvenc?" -c:v "+codec+"_nvenc -gpu "+Math.Max(0,r.GpuIndex)+" -preset p1 -tune ll -rc vbr -cq "+quality:" -c:v "+(codec=="hevc"?"libx265":"libx264")+" -preset ultrafast -crf "+quality;if(!r.UseNvenc&&codec=="hevc")result+=" -x265-params pools=4:frame-threads=2";if(r.MaxMbps>0){int min=Math.Max(1,r.MinMbps),max=r.MaxMbps;result+=" -b:v "+((min+max)/2)+"M -minrate "+min+"M -maxrate "+max+"M -bufsize "+(max*2)+"M";}return result;}
  public static void Validate(RecordingRequest r){if(Array.IndexOf(Rates,r.Fps)<0)throw new ArgumentException("Selecione 30, 60, 120 ou 240 FPS.");if(r.Codec!=null&&r.Codec!="H.264"&&r.Codec!="H.265")throw new ArgumentException("Codec inválido.");if(r.Container!=null&&r.Container!="MP4"&&r.Container!="AVI")throw new ArgumentException("Formato inválido.");if(r.Container=="AVI"&&r.Codec=="H.265")throw new ArgumentException("Para H.265, selecione MP4. AVI usa H.264.");if(r.MaxMbps>0&&(r.MinMbps<1||r.MinMbps>r.MaxMbps||r.MaxMbps>500))throw new ArgumentException("Bitrate: mínimo deve ser positivo e não ultrapassar o máximo (até 500 Mb/s).");}
  public static void Apply(Preferences p,RecordingRequest r){r.Fps=p.VideoFps;r.UseNvenc=p.VideoNvenc;r.GpuIndex=p.VideoGpu;r.Codec=p.VideoCodec;r.Container=p.VideoContainer;r.Resolution=p.VideoResolution;r.Quality=p.VideoQuality;r.MinMbps=p.VideoMinMbps;r.MaxMbps=p.VideoMaxMbps;r.SeparateMp3=p.SeparateMp3;}
 }
 class FpsChoice:DarkChoice { public decimal Value{get{return SelectedItem==null?30:(int)SelectedItem;}set{SelectedItem=VideoProfiles.NormalizeFps((int)value);}}public FpsChoice(){foreach(int n in VideoProfiles.Rates)Items.Add(n);SelectedIndex=0;} }
 class EncodingSettingsControl:Panel {
  FpsChoice fps;DarkChoice processor,codec,container,resolution,quality;NumericUpDown min,max;CheckBox mp3;Label hint;
  public EncodingSettingsControl(Preferences p){Size=new Size(640,430);BackColor=Brand.Panel;ForeColor=Brand.Ink;Add("FPS",12,12);fps=new FpsChoice{Location=new Point(210,8),Width=400};Controls.Add(fps);fps.Value=p.VideoFps;
   Add("Processamento",12,56);processor=Choice(210,52,400,VideoProfiles.Encoders().ToArray(),null);foreach(EncoderChoice e in processor.Items)if(e.Index==(p.VideoNvenc?p.VideoGpu:-1))processor.SelectedItem=e;if(processor.SelectedIndex<0)processor.SelectedIndex=0;
   Add("Formato do arquivo",12,100);container=Choice(210,96,180,new object[]{"MP4","AVI"},p.VideoContainer);codec=Choice(406,96,204,new object[]{"H.264","H.265"},p.VideoCodec);
   Add("Resolução de saída",12,144);resolution=Choice(210,140,400,new object[]{"Original","720p","1080p","1440p","2160p"},p.VideoResolution);Add("1440p = 2560 × 1440 · 2160p = 4K · em 16:9",210,178);
   Add("Qualidade",12,215);quality=Choice(210,211,400,new object[]{"Leve","Equilibrada","Alta"},p.VideoQuality);
   Add("Bitrate mínimo / máximo",12,259);min=Number(p.VideoMinMbps,210,255);max=Number(p.VideoMaxMbps,360,255);Add("Mb/s",510,259);
   mp3=new CheckBox{Text="Também salvar áudio separado · MP3 320 kb/s",Checked=p.SeparateMp3,Location=new Point(12,307),AutoSize=true};Controls.Add(mp3);
   hint=new Label{Text="O áudio continua no vídeo. MP3 só é gerado quando houver áudio.\nBitrate VBR: limites orientam o encoder; cenas estáticas podem usar menos.\nO FPS escolhido é alvo; o resultado efetivo será informado ao concluir.",Location=new Point(12,350),Size=new Size(610,72),ForeColor=Brand.Muted};Controls.Add(hint);
   resolution.SelectedIndexChanged+=delegate{int h=resolution.SelectedItem.ToString()=="720p"?720:resolution.SelectedItem.ToString()=="2160p"?2160:resolution.SelectedItem.ToString()=="1440p"?1440:1080;int lo=h>=2160?40:h>=1440?20:h>=1080?10:5;min.Value=lo;max.Value=lo*2;};
  }
  public void Read(Preferences p){p.VideoFps=(int)fps.Value;var gpu=(EncoderChoice)processor.SelectedItem;p.VideoNvenc=gpu.Index>=0;p.VideoGpu=gpu.Index;p.VideoCodec=codec.SelectedItem.ToString();p.VideoContainer=container.SelectedItem.ToString();p.VideoResolution=resolution.SelectedItem.ToString();p.VideoQuality=quality.SelectedItem.ToString();p.VideoMinMbps=(int)min.Value;p.VideoMaxMbps=(int)max.Value;p.SeparateMp3=mp3.Checked;var r=new RecordingRequest();VideoProfiles.Apply(p,r);VideoProfiles.Validate(r);}
  void Add(string s,int x,int y){Controls.Add(new Label{Text=s,Location=new Point(x,y),AutoSize=true,ForeColor=Brand.Ink});}
  DarkChoice Choice(int x,int y,int w,object[] values,object selected){var c=new DarkChoice{Location=new Point(x,y),Width=w};c.Items.AddRange(values);c.SelectedItem=selected;if(c.SelectedIndex<0&&values.Length>0)c.SelectedIndex=0;Controls.Add(c);return c;}
  NumericUpDown Number(int n,int x,int y){var c=new NumericUpDown{Minimum=1,Maximum=500,Value=Math.Max(1,Math.Min(500,n)),Location=new Point(x,y),Width=120,BackColor=Brand.Back,ForeColor=Brand.Ink};Controls.Add(c);return c;}
 }
}
